 /** Supported languages, the first is the fallback. */
 export const LANGUAGES = Object.keys(MESSAGES);

+/** Chooses a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (!header) return fallback;
+  const raw = Array.isArray(header) ? header.join(",") : String(header);
+  const candidates = raw
+    .split(",")
+    .map((part, index) => {
+      const [tagPart, ...params] = part.split(";").map((s) => s.trim());
+      if (!tagPart) return null;
+      const primary = tagPart.toLowerCase().split("-")[0];
+      let q = 1;
+      for (const p of params) {
+        const m = /^q\s*=\s*(.+)$/i.exec(p);
+        if (m) q = Number(m[1]);
+      }
+      if (!Number.isFinite(q) || q <= 0 || q > 1) return null;
+      return { primary, q, index };
+    })
+    .filter((c) => c && LANGUAGES.includes(c.primary))
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  return candidates[0]?.primary ?? fallback;
+}
